        {
          "id": "b1",
          "kind": "process",
          "text": "buf = deque()"
        },
        {
          "id": "b2",
          "kind": "process",
          "text": "empty = Semaphore(N)    # 빈 칸 수"
        },
        {
          "id": "b3",
          "kind": "process",
          "text": "full = Semaphore(0)     # 찬 칸 수"
        },
        {
          "id": "b4",
          "kind": "process",
          "text": "mutex = Lock()"
        },
        {
          "id": "b5",
          "kind": "parallel",
          "text": "",
          "branches": [
            {
              "id": "r1",
              "body": [
                {
                  "id": "b6",
