                  "target": {
                    "kind": "local",
                    "diagram": "d2"
                  },
                  "args": "",
                  "result": ""
                }
              ]
            },
            {
              "id": "r2",
              "body": [
                {
                  "id": "b7",
                  "kind": "call",
                  "target": {
                    "kind": "local",
                    "diagram": "d3"
                  },
                  "args": "",
                  "result": ""
                }
              ]
            }
          ]
        },
        {
          "id": "b8",
          "kind": "process",
          "text": "print(\"둘 다 끝남\")"
        }
      ]
    },
    {
      "id": "d2",
      "head": {
        "kind": "method",
        "text": "producer()"
      },
      "body": [
        {
          "id": "b9",
          "kind": "endless",
          "body": [
            {
              "id": "b10",
              "kind": "process",
              "text": "item = produce()    # 다 만들면 None"
            },
            {
              "id": "b11",
              "kind": "process",
              "text": "empty.acquire()     # 빈 칸이 날 때까지 기다린다"
            },
            {
              "id": "b12",
              "kind": "process",
              "text": "with mutex: buf.append(item)"
            },
            {
              "id": "b13",
              "kind": "process",
              "text": "full.release()"
            },
            {
              "id": "b14",
              "kind": "if",
              "text": "item is None",
              "yes": {
                "id": "r3",
                "body": [
                  {
                    "id": "b15",
                    "kind": "exit",
                    "text": "break    # 끝 표시까지 넣었다"
                  }
                ]
              },
              "no": {
                "id": "r4",
                "body": [
                  {
                    "id": "b16",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            }
          ]
        }
      ]
    },
    {
      "id": "d3",
      "head": {
        "kind": "method",
        "text": "consumer()"
      },
      "body": [
        {
          "id": "b17",
          "kind": "endless",
          "body": [
            {
              "id": "b18",
              "kind": "process",
              "text": "full.acquire()    # 찬 칸이 생길 때까지 기다린다"
            },
            {
              "id": "b19",
              "kind": "process",
              "text": "with mutex: item = buf.popleft()"
            },
            {
              "id": "b20",
              "kind": "process",
              "text": "empty.release()"
            },
            {
              "id": "b21",
              "kind": "if",
              "text": "item is None",
              "yes": {
                "id": "r5",
                "body": [
                  {
                    "id": "b22",
                    "kind": "exit",
                    "text": "break    # 끝 표시를 받았다"
                  }
                ]
              },
              "no": {
                "id": "r6",
                "body": [
                  {
                    "id": "b23",
                    "kind": "process",
                    "text": ""
                  }
                ]
              }
            },
            {
              "id": "b24",
              "kind": "process",
              "text": "consume(item)"
            }
          ]
        }
      ]
    }
